def _backfill_default_shop(apps, schema_editor):
    """Put every existing row into one default Shop so the multi-shop rollout
    upgrades an already-running deployment without touching data."""
    model_names = [
        "Category",
        "Item",
        "Sale",
        "SaleItem",
        "StockAdjustment",
        "PartialPayment",
        "PaymentRecord",
        "Service",
        "ServiceEntry",
        "Expense",
        "AdminUser",
    ]
    has_rows = any(
        apps.get_model("sales", name).objects.exists() for name in model_names
    )
    if not has_rows:
        return
    shop, _ = apps.get_model("sales", "Shop").objects.get_or_create(name="Main Store")
    for name in model_names:
        apps.get_model("sales", name).objects.filter(shop__isnull=True).update(
            shop_id=shop.pk
        )


